mapper.select:
SELECT P.PORTFOLIO_ID id, P.PORTFOLIO_NAME text, DATE_FORMAT(P.VDATE,'%Y-%m-%d') object FROM PTL_PORTFOLIO P LEFT JOIN PTL_PORTFOLIO_AUTHORITY AU ON P.PORTFOLIO_ID = AU.PORTFOLIO_ID
AND (P.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR P.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{initValue}
AND AU.USER_ID = #{userId}
AND P.PORTFOLIO_TYPE = #{PORT_TYPE}

SELECT P.PORTFOLIO_ID code, P.PORTFOLIO_NAME shortName， DATE_FORMAT(P.VDATE,'%Y-%m-%d') hidCode FROM PTL_PORTFOLIO P LEFT JOIN PTL_PORTFOLIO_AUTHORITY AU ON P.PORTFOLIO_ID = AU.PORTFOLIO_ID
AND (P.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{param},'%')) OR P.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{param},'%')))
AND P.PORTFOLIO_ID = #{initValue}
AND AU.USER_ID = #{userId}
AND P.PORTFOLIO_TYPE = #{PORT_TYPE}

	SELECT 
	    DATE_FORMAT(MAX(T.MDATE),'%Y-%m-%d')
	FROM TRD_FIN_PRODUCT_DEAL_TOTAL T 
	  INNER JOIN
	       STL_CAPACCT_INFO S
	  ON T.FINPROD_ID = S.ACCT_NO
	WHERE 1=1

     	AND S.BUSI_ACCT_NO = #{acctNo}

	AND T.TRADE_STATUS = #{TRADE_STATUS_01}
    AND T.IS_CANCEL = #{YES_OR_NO_N}

	select
		IFNULL(PTL.TDY_INTINCEXP,0)
		- (SELECT
			IFNULL(SUM(IFNULL(T2.TRADE_AMT, 0)),0)
			FROM
				PTL_TRADE T1
			INNER JOIN
				TRD_PRODUCT_DEAL T2
			ON
				T1.BUSI_NO = T2.TRADE_ID
				AND T1.BUSI_TYPE = #{BUSI_TYPE}
				AND T2.TRADE_STATUS = #{TRADE_STATUS_01}
				AND T2.IS_CANCEL = #{IS_CANCEL_N}
				AND T2.MDATE = STR_TO_DATE(#{mdate},'%Y-%m-%d')
			WHERE
				T1.PORTFOLIO_ID = #{portfolioId}
				AND T1.BUSI_ID = #{busiAcctNo}
				)  TRADE_AMT
  	from (SELECT max(TDY_INTINCEXP) TDY_INTINCEXP, PORTFOLIO_ID, FINPROD_ID
		FROM PTL_SEC_VALUTION
		WHERE CDATE = #{lastDay,jdbcType=DATE}
		and PORTFOLIO_ID = #{portfolioId}
		and FINPROD_ID = #{busiAcctNo}
		GROUP BY PORTFOLIO_ID, FINPROD_ID) PTL

		PTL.PORTFOLIO_ID = #{portfolioId}
		and PTL.FINPROD_ID = #{busiAcctNo}
